import os, csv, json
from pathlib import Path
from collections import deque

pd = Path(os.environ["PIPELINE_FLOW_DIR"]) / "20190114_pipeline.csv"
rows = list(csv.DictReader(open(pd, encoding="utf-8-sig")))

adj = {}
for r in rows:
    adj.setdefault(r["起点站名"], []).append((r["终点站名"], r["管道划分"]))

target = "南通站"
sources = ["靖边站", "榆林站", "黑河首站", "霍尔果斯首站"]

# BFS on reversed graph: from target back along edges, but keep forward order for output
radj = {}
for u, outs in adj.items():
    for v, pl in outs:
        radj.setdefault(v, []).append((u, pl))

out = {}
for s in sources:
    prev = {target: None}
    dq = deque([target])
    while dq:
        cur = dq.popleft()
        if cur == s:
            break
        for u, pl in radj.get(cur, []):
            if u not in prev:
                prev[u] = (cur, pl)
                dq.append(u)
    if s not in prev:
        out[s] = {"reachable": False}
        continue
    path = []
    cur = s
    while prev[cur] is not None:
        nxt, pl = prev[cur]
        path.append({"source": cur, "target": nxt, "pipeline": pl})
        cur = nxt
    out[s] = {"reachable": True, "hops": len(path), "path": path}

print(json.dumps(out, ensure_ascii=False, indent=1))

