import os, csv, json
from collections import deque
from pathlib import Path

NODE = Path(os.environ["NODE_FLOW_DIR"]) / "20191206_node.csv"
PIPE = Path(os.environ["PIPELINE_FLOW_DIR"]) / "20191206_pipeline.csv"

sources = {}
with NODE.open(encoding="utf-8-sig") as f:
    for r in csv.DictReader(f):
        if r["类型"] == "气源":
            sources.setdefault(r["站名"], []).append(r["管道划分"])

edges = []
with PIPE.open(encoding="utf-8-sig") as f:
    for r in csv.DictReader(f):
        edges.append((r["起点站名"], r["终点站名"], r["管道划分"], r["管道流量"]))

adj = {}
for a, b, p, fl in edges:
    adj.setdefault(a, []).append((b, p, fl))
    adj.setdefault(b, []).append((a, p, fl))

def shortest(src, dst):
    q = deque([(src, [])])
    seen = {src}
    while q:
        cur, path = q.popleft()
        if cur == dst:
            return path
        for nxt, p, fl in sorted(adj.get(cur, []), key=lambda x: (x[0], x[1])):
            if nxt not in seen:
                seen.add(nxt)
                q.append((nxt, path + [{"from": cur, "to": nxt, "pipeline": p, "flow": fl}]))
    return None

res = {"sources": {k: v for k, v in sources.items()}}
for s in ["靖边站", "榆林站", "黑河首站", "霍尔果斯首站"]:
    p = shortest(s, "永清站")
    res[s] = {"hops": None if p is None else len(p), "path": p}

print(json.dumps(res, ensure_ascii=False, indent=1))

