import os, json, csv, statistics
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190127", "20190128", "20190129"]
line = "川气东送"

series = {}   # (o,d) -> {date: value}
order = []
for d in dates:
    with open(DIR / f"{d}_pipeline.csv", encoding="utf-8") as f:
        for r in csv.DictReader(f):
            if r["管道划分"] != line:
                continue
            key = (r["起点站名"], r["终点站名"])
            if key not in series:
                series[key] = {}
                order.append(key)
            series[key][d] = float(r["管道流量"])

rows = []
for key in order:
    vals = [series[key].get(d) for d in dates]
    if any(v is None for v in vals):
        continue
    rows.append({
        "start": key[0],
        "end": key[1],
        "values": items_v if False else {d: series[key][d] for d in dates},
        "stdev_pop": statistics.pstdev(vals),
        "stdev_sample": statistics.stdev(vals),
        "mean": sum(vals) / len(vals),
    })

rows.sort(key=lambda x: x["stdev_pop"], reverse=True)
print(json.dumps(rows, ensure_ascii=False, indent=2, default=str))

import os, csv
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20191203", "20191204", "20191205"]
target = "西气东输二线"

data = {}
for d in dates:
    with (DIR / f"{d}_pipeline.csv").open(encoding="utf-8-sig") as f:
        for x in csv.DictReader(f):
            if x["管道划分"] == target and x["类型"] == "管段":
                data.setdefault((x["起点站名"], x["终点站名"]), {})[d] = float(x["管道流量"])

best = None
for k, m in sorted(data.items()):
    if len(m) != 3:
        continue
    for i in (1, 2):
        ch = m[dates[i]] - m[dates[i-1]]
        pct = ch / m[dates[i-1]] * 100
        rec = (abs(ch), k, dates[i-1], dates[i], round(ch, 3), round(pct, 3))
        if best is None or rec[0] > best[0]:
            best = rec

print("单管段最大绝对日环比变化:", best[1], best[2], "->", best[3], "变化=", best[4], "相对%=", best[5])

tot = [sum(m[d] for m in data.values()) for d in dates]
print("总量:", [round(t, 3) for t in tot])
print("最大单日总输量环比:", round(max(abs(tot[1]-tot[0]), abs(tot[2]-tot[1])), 3))
print("峰值总量日:", dates[tot.index(max(tot))], round(max(tot), 3))

import os, json, csv
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20191203", "20191204", "20191205", "20191206", "20191207"]
trunks = ["川气东送", "西气东输二线"]

daily = {t: {} for t in trunks}
counts = {t: {} for t in trunks}
for d in dates:
    p = DIR / f"{d}_pipeline.csv"
    with open(p, newline="", encoding="utf-8-sig") as f:
        for row in csv.DictReader(f):
            t = (row["管道划分"] or "").strip()
            if t in daily:
                v = float(row["管道流量"])
                daily[t].setdefault(d, []).append(v)

out = {}
for t in trunks:
    per_day = {d: sum(v) / len(v) for d, v in daily[t].items()}
    counts[t] = {d: len(v) for d, v in daily[t].items()}
    vals = list(per_day.values())
    out[t] = {
        "segment_count": counts[t],
        "daily_mean": per_day,
        "grand_mean": sum(vals) / len(vals),
        "range": max(vals) - min(vals),
        "max_day": max(per_day, key=per_day.get),
        "min_day": min(per_day, key=per_day.get),
        "range_percent_of_mean": (max(vals) - min(vals)) / (sum(vals) / len(vals)) * 100,
    }

