            name = r["站名"].strip()
            if name in targets:
                fl = r["计算流量"].strip() or r["输入流量"].strip()
                rows.setdefault(name, {}).setdefault(d, []).append({
                    "pipeline": r["管道划分"].strip(),
                    "type": r["类型"].strip(),
                    "control": r["控制类型"].strip(),
                    "flow": abs(float(fl)),
                })

out = {}
for name in targets:
    per_day = {}
    for d in dates:
