            "stdev_pop": round(statistics.pstdev(vals), 3) if len(vals) > 1 else 0.0,
            "cv_pct": round(statistics.pstdev(vals) / statistics.mean(vals) * 100, 3) if len(vals) > 1 else 0.0,
        }
    dm = [per_day[d]["mean"] for d in dates]
    ds = [per_day[d]["sum"] for d in dates]
    bd = [per_day[d]["mean"] for d in dates]  # daily-mean series
    out[name] = {
        "per_day": per_day,
        "mean_of_daily_means": round(statistics.mean(dm), 3),
        "mean_of_daily_sums": round(statistics.mean(ds), 3),
        "daily_mean_series": dm,
        "day_over_day_change_pct": round((dm[1] - dm[0]) / dm[0] * 100, 3),
        "volatility_between_days_pct": round(statistics.pstdev(dm) / statistics.mean(dm) * 100, 3),
        "within_day_cv_avg_pct": round(statistics.mean([per_day[d]["cv_pct"] for d in dates]), 3),
    }

