import os, csv, json
from pathlib import Path
from statistics import mean

DIR = Path(os.environ["NODE_FLOW_DIR"])
dates = ["20190101", "20190102", "20190103"]

rows = []
for d in dates:
    with open(DIR / f"{d}_node.csv", encoding="utf-8-sig") as f:
        for r in csv.DictReader(f):
            raw = r["计算流量"].strip() or r["输入流量"].strip()
            rows.append({
                "date": d,
                "line": r["管道划分"].strip(),
                "station": r["站名"].strip(),
                "type": r["类型"].strip(),
                "ctrl": r["控制类型"].strip(),
                "flow": float(raw),
                "abs": abs(float(raw)),
            })

print("total rows:", len(rows))

# aggregate by station name (all pipeline records pooled)
byst = {}
for r in rows:
    byst.setdefault(r["station"], []).append(r)

rank = sorted(byst.items(), key=lambda kv: (-mean(x["abs"] for x in kv[1]), kv[0]))
print("\n== TOP 10 by station-name mean |flow| (pooled over all lines & days) ==")
for name, rs in rank[:10]:
    vals = [x["abs"] for x in rs]
    print(f"{name}\tn={len(rs)}\tmean={mean(vals):.3f}\tmin={min(vals):.3f}\tmax={max(vals):.3f}")

print("\n== TOP 10 by (line,station) node mean |flow| ==")
bynode = {}
for r in rows:
    bynode.setdefault((r["line"], r["station"]), []).append(r)
nrank = sorted(bynode.items(), key=lambda kv: (-mean(x["abs"] for x in kv[1]), kv[0]))
for k, rs in nrank[:10]:
    print(f"{k[0]}/{k[1]}\tn={len(rs)}\tmean={mean(x['abs'] for x in rs):.3f}")

print("\n== 武汉站 detail ==")
for k, rs in sorted(bynode.items()):
    if k[1] == "武汉站":
        for x in sorted(rs, key=lambda y: y["date"]):
            print(k, x["date"], x["type"], x["ctrl"], x["flow"], x["abs"])
        print("mean:", mean(x["abs"] for x in rs))

out = {
    "dates": dates,
    "row_count": len(rows),
    "top5_station_name": [
        {"station": name, "records": len(rs), "mean_abs": round(mean(x["abs"] for x in rs), 3),
         "min_abs": round(min(x["abs"] for x in rs), 3), "max_abs": round(max(x["abs"] for x in rs), 3)}
        for name, rs in rank[:5]
    ],
    "top5_nodes": [
        {"line": k[0], "station": k[1], "records": len(rs), "mean_abs": round(mean(x["abs"] for x in rs), 3)}
        for k, rs in nrank[:5]
    ],
}
