import os, json, csv
from pathlib import Path

DIR = Path(os.environ["NODE_FLOW_DIR"])
OUT = Path(os.environ["OUTPUT_DIR"])
dates = ["20191106", "20191107", "20191118"]
stations = ["靖边站", "南通站"]

daily = {}   # station -> {date: sum}
detail = {}
for d in dates:
    p = DIR / f"{d}_node.csv"
    sums = {s: 0.0 for s in stations}
    rows_detail = {s: [] for s in stations}
    with p.open(encoding="utf-8-sig", newline="") as f:
        for row in csv.DictReader(f):
            name = (row.get("站名") or "").strip()
            if name in sums:
                raw = (row.get("计算流量") or "").strip()
                if raw == "":
                    raw = (row.get("输入流量") or "").strip()
                v = abs(float(raw))
                sums[name] += v
                rows_detail[name].append([row.get("管道划分"), v])
    for s in stations:
        daily.setdefault(s, {})[d] = round(sums[s], 3)
        detail.setdefault(s, {})[d] = rows_detail[s]

res = {"daily_abs_flow": daily, "detail": detail}

# peak day overall across window (sum of the two stations' absolute flow)
tot = {d: round(sum(daily[s][d] for s in stations), 3) for d in dates}
res["daily_combined_total"] = tot
peak_day = max(tot, key=lambda k: tot[k])
res["peak_day_combined"] = peak_day
res["peak_day_each"] = {s: max(daily[s], key=lambda k: daily[s][k]) for s in stations}

res["cum_full"] = {s: round(sum(daily[s].values()), 3) for s in stations}
keep = [d for d in dates if d != peak_day]
res["days_kept"] = keep
res["cum_without_peak"] = {s: round(sum(daily[s][d] for d in keep), 3) for s in stations}
a, b = stations
res["ranking_full"] = sorted(stations, key=lambda s: -res["cum_full"][s])
res["ranking_without_peak"] = sorted(stations, key=lambda s: -res["cum_without_peak"][s])
res["reversal"] = res["ranking_full"] != res["ranking_without_peak"]
res["diff_full"] = round(res["cum_full"][a] - res["cum_full"][b], 3)
res["diff_without_peak"] = round(res["cum_without_peak"][a] - res["cum_without_peak"][b], 3)

print(json.dumps(res, ensure_ascii=False, indent=1, default=str))
OUT.mkdir(parents=True, exist_ok=True)
(OUT / "drop_peak_result.json").write_text(json.dumps(res, ensure_ascii=False, indent=1, default=str), encoding="utf-8")

import os, csv, json, statistics
from pathlib import Path

DIR = Path(os.environ["NODE_FLOW_DIR"])
dates = ["20190425", "20190510", "20191001", "20191013"]
targets = ["安平站", "潼关站"]

raw = {}   # station -> {date: [ (pipeline, type, ctrl, val) ]}
for d in dates:
    p = DIR / f"{d}_node.csv"
    with p.open(encoding="utf-8-sig") as f:
        for r in csv.DictReader(f):
            name = r["站名"].strip()
            if name not in targets:
                continue
            v = r["计算流量"].strip()
            if v == "":
                continue
            raw.setdefault(name, {}).setdefault(d, []).append(
                (r["管道划分"].strip(), r["类型"].strip(), r["控制类型"].strip(), float(v))
            )

out = {}
for st in targets:
    per_date_total = {}
    per_date_detail = {}
    for d in dates:
        recs = raw.get(st, {}).get(d, [])
        per_date_detail[d] = [
            {"pipeline": pl, "type": ty, "control": ct, "calc_flow": val} for pl, ty, ct, val in recs
        ]
        per_date_total[d] = round(sum(abs(x[3]) for x in recs), 3) if recs else None

    totals = [per_date_total[d] for d in dates]
    mean = statistics.fmean(totals)
    sd_pop = statistics.pstdev(totals)
    sd_samp = statistics.stdev(totals)
    out[st] = {
        "daily_total": per_date_total,
        "detail": per_date_detail,
        "mean_daily": round(mean, 3),
        "min_daily": min(totals),
        "max_daily": max(totals),
        "range": round(max(totals) - min(totals), 3),
        "sd_population": round(sd_pop, 3),
        "sd_sample": round(sd_samp, 3),
        "cv_population_pct": round(sd_pop / mean * 100, 2),
        "cv_sample_pct": round(sd_samp / mean * 100, 2),
        "peak_to_trough_pct": round((max(totals) - min(totals)) / mean * 100, 2),
    }

# per-pipeline means for context
per_line = {}
for st in targets:
    for d in dates:
        for rec in out[st]["detail"][d]:
            key = (rec["pipeline"])
            per_line.setdefault(st, {}).setdefault(key, []).append(rec["calc_flow"])
per_line_summary = {
    st: {pl: {"n": len(v), "mean": round(statistics.fmean(v), 3),
              "min": min(v), "max": max(v),
              "cv_population_pct": round(statistics.pstdev(v) / statistics.fmean(v) * 100, 2)}
         for pl, v in lines.items()}
    for st, lines in per_line.items()
}

print(json.dumps({"stations": out, "per_pipeline": per_line_summary}, ensure_ascii=False, indent=1, default=str))

