import os, csv, json
from pathlib import Path
from decimal import Decimal

DIR = Path(os.environ["NODE_FLOW_DIR"])
OUT = Path(os.environ["OUTPUT_DIR"])
dates = ["20191102", "20191103", "20191104", "20191105"]
targets = ["武汉站", "通州南站"]

records = {}
for d in dates:
    p = DIR / f"{d}_node.csv"
    with open(p, encoding="utf-8-sig", newline="") as f:
        rd = csv.DictReader(f)
        for row in rd:
            name = (row.get("站名") or "").strip()
            if name not in targets:
                continue
            fld = row.get("计算流量")
            if fld is None or str(fld).strip() == "":
                fld = row.get("输入流量")
            if fld is None or str(fld).strip() == "":
                continue
            val = Decimal(str(fld).strip())
            records.setdefault(name, []).append({
                "date": d,
                "pipeline": (row.get("管道划分") or "").strip(),
                "type": (row.get("类型") or "").strip(),
                "control": (row.get("控制类型") or "").strip(),
                "raw": str(val),
                "abs": str(abs(val)),
            })

summary = {}
for name in targets:
    rows = records.get(name, [])
    total = sum((Decimal(r["abs"]) for r in rows), Decimal("0"))
    per_pipe = {}
    for r in rows:
        per_pipe.setdefault(r["pipeline"], Decimal("0"))
        per_pipe[r["pipeline"]] += Decimal(r["abs"])
    per_day = {}
    for r in rows:
        per_day.setdefault(r["date"], Decimal("0"))
        per_day[r["date"]] += Decimal(r["abs"])
    summary[name] = {
        "record_count": len(rows),
        "records": rows,
        "cumulative_abs_flow": str(total),
        "by_pipeline": {k: str(v) for k, v in per_pipe.items()},
        "by_date": {k: str(v) for k, v in per_day.items()},
    }

payload = {"window": {"start": dates[0], "end": dates[-1], "files": [f"{d}_node.csv" for d in dates]},
           "stations": summary}
OUT.mkdir(parents=True, exist_ok=True)
with open(OUT / "node_flow_window_agg_20191102_20191105.json", "w", encoding="utf-8") as f:
    f.write(json.dumps(payload, ensure_ascii=False, indent=2, default=str))
print(json.dumps(payload, ensure_ascii=False, indent=2, default=str))

